def task(tag, n):
    for i in range(1, n + 1):
        yield f'{tag} step {i}'
log = []
active = [(task('alpha', 2), 'alpha'), (task('beta', 2), 'beta')]
while active:
    nxt = []
    for t, tag in active:
        try:
            step = next(t)
            log.append(step)
            nxt.append((t, tag))
        except StopIteration:
            log.append(f'{tag} done')
    active = nxt
print('\n'.join(log))

