def rle_encode(s):
    out = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out.append((s[i], j - i))
        i = j
    return out
def rle_decode(pairs):
    return ''.join(ch * n for ch, n in pairs)
orig = 'AAAABBBCCDAA'
enc = rle_encode(orig)
print('encoded:', enc)
print('round trip ok:', rle_decode(enc) == orig)

blocks = {}
def alloc(name, data):
    blocks[name] = {'guard_before': 0xDEAD, 'data': data, 'guard_after': 0xBEEF}
def sweep():
    for name, b in blocks.items():
        good = b['guard_before'] == 0xDEAD and b['guard_after'] == 0xBEEF
        print(f'{name}: guard {"ok" if good else "CORRUPT"}')
alloc('A', 'hello')
alloc('B', 'world')
blocks['B']['guard_after'] = 0x0000
sweep()

checksum = 0
for tick in range(1, 11):
    events = []
    if tick == 3:
        events = ['beep']
    if tick == 7:
        events = ['reschedule']
    if tick == 10:
        events = ['report']
    for e in events:
        checksum = (checksum + sum(e.encode())) % 100000
    print(f'tick {tick}: events {len(events)} checksum {checksum}')
print('final checksum:', checksum)

